SET plan_cache_mode=force_custom_plan; SET statement_timeout=120000; PREPARE hfs1579 AS SELECT COUNT(*) FROM resources WHERE tenant_id = $1 AND resource_type = $2 AND is_deleted = FALSE AND (((id IN (SELECT resource_id FROM search_index WHERE tenant_id = $1 AND resource_type = $2 AND param_name = 'patient' AND ((value_reference IS NOT NULL AND split_part(value_reference, '/', -1) = $3)))) AND (id IN (SELECT resource_id FROM search_index WHERE tenant_id = $1 AND resource_type = $2 AND param_name = 'code' AND (value_token_code = $4)))) AND (EXISTS (WITH scoped_quantity AS MATERIALIZED (SELECT * FROM search_index WHERE tenant_id = $1 AND resource_type = $2 AND resource_id = resources.id AND param_name = 'value-quantity') SELECT 1 FROM scoped_quantity WHERE ((value_quantity_value > $5 AND value_quantity_unit = $6) OR (value_quantity_canonical_value > $7 AND value_quantity_canonical_unit = $8)))));
EXPLAIN (ANALYZE, BUFFERS, FORMAT JSON) EXECUTE hfs1579('default','Observation','7d24f7a0-6f2e-ce3b-5568-db7b14695583','8302-2',100.0,'cm',1.0,'m');
